package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import com.ruoyi.paiflow.mapper.ToolMapper;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.transaction.annotation.*;
import static com.ruoyi.paiflow.service.ModelOperationJson.error;

/** 工具维护、旧格式兼容和版本使用同一中心Service，不调用旧Link CRUD/Redis。 */
@Service @ConditionalOnProperty(prefix="paiflow",name={"enabled","tools.enabled"},havingValue="true")
public class ToolService {
 public record Page(List<JSONObject> records,long total,int current,int size,long pages) {}
 private final ToolMapper mapper;private final ResourceAccessService access;private final IdentityMappingService identities;private DefaultPersonalSpaceService defaults;
 public ToolService(ToolMapper mapper,ResourceAccessService access,IdentityMappingService identities){this.mapper=mapper;this.access=access;this.identities=identities;}
 @Autowired public void useDefaultSpaces(DefaultPersonalSpaceService d){defaults=d;}
 public Long scope(String header,Object echoed,String permission,boolean write){if(defaults==null)throw error("默认个人域未装配",503);var selected=defaults.select(header,echoed,permission);return write?defaults.materialize(selected,permission):defaults.existing(selected,permission);}
 public JSONObject detail(long id,Long space){return detail(id,space,false);}
 public JSONObject detail(long id,Long space,boolean draft){var row=require(id,space,"paiflow:tool:query",false);if(draft&&row.get("draftConfigurationJson") instanceof String json){var saved=JSON.parseObject(json);row=new LinkedHashMap<>(row);row.put("name",saved.get("name"));row.put("configurationJson",saved.getJSONObject("configuration").toJSONString(JSONWriter.Feature.WriteMapNullValue));}return view(row);}
 public Page list(Long space,int page,int size,String search){return list(space,page,size,search,null);}
 public Page list(Long space,int page,int size,String search,Integer status){if(page<1||size<1||size>200||status!=null&&status!=0&&status!=1)throw error("工具分页/状态无效",400);if(space==null)return new Page(List.of(),0,page,size,0);access.requireSpace(space,"paiflow:tool:query",3,false);String s=search==null?"":search;Integer temporary=status==null?null:1-status;long count=mapper.count(space,s,temporary);return new Page(mapper.list(space,(long)(page-1)*size,size,s,temporary).stream().map(this::view).toList(),count,page,size,(count+size-1)/size);}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED)
 public JSONObject create(String header,JSONObject body,boolean temporary){if(body.get("id")!=null)return saveExisting(header,body,temporary);String plugin=UUID.randomUUID().toString().replace("-","");var effective=ToolOpenApi.copy(body);if(effective.get("appId")!=null&&!(effective.get("appId") instanceof String))throw error("原appId必须为字符串兼容标签",422);if(effective.get("appId")==null||effective.getString("appId").isBlank())effective.put("appId",plugin);var config=configuration(effective);String name=ToolSchema.text(body.get("name"),128,"工具名称");long owner=access.requirePermission("paiflow:tool:add");Long space=scope(header,body.get("spaceId"),"paiflow:tool:add",true);access.requireSpace(space,"paiflow:tool:add",2,true);
  var row=new LinkedHashMap<String,Object>();row.put("spaceId",space);row.put("ownerUserId",owner);row.put("pluginId",plugin);row.put("name",name);row.put("configurationJson",config.toJSONString(JSONWriter.Feature.WriteMapNullValue));row.put("temporary",temporary?1:0);row.put("actor",identities.current().getUsername());if(mapper.insert(row)!=1)throw error("工具保存失败",500);if(!temporary)snapshot(row,"V1.0");return view(mapper.find(((Number)row.get("id")).longValue()));}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED)
 public JSONObject update(long id,Long space,Long revision,JSONObject body){var row=require(id,space,"paiflow:tool:edit",true);revision(row,revision);var config=configuration(preserveAuthentication(row,body));row.put("name",ToolSchema.text(body.get("name"),128,"工具名称"));row.put("configurationJson",config.toJSONString(JSONWriter.Feature.WriteMapNullValue));row.put("draftConfigurationJson",null);row.put("actor",identities.current().getUsername());if(mapper.update(row)!=1)throw error("工具版本已改变",409);if(number(row,"temporary")==0){String next="V"+(number(row,"revision")+2)+".0";snapshot(row,next);}return view(mapper.find(id));}
 private JSONObject saveExisting(String header,JSONObject body,boolean temporary){long id=body.getLongValue("id");Long selected=scope(header,body.get("spaceId"),"paiflow:tool:edit",false);var row=require(id,selected,"paiflow:tool:edit",true);revision(row,body.getLong("revision"));var config=configuration(preserveAuthentication(row,body));String name=ToolSchema.text(body.get("name"),128,"工具名称");if(temporary&&number(row,"temporary")==0)row.put("draftConfigurationJson",JSONObject.of("name",name,"configuration",config).toJSONString(JSONWriter.Feature.WriteMapNullValue));else{if(!temporary&&number(row,"temporary")==0)throw error("正式工具需使用update保持版本冲突保护",409);row.put("name",name);row.put("configurationJson",config.toJSONString(JSONWriter.Feature.WriteMapNullValue));row.put("draftConfigurationJson",null);row.put("temporary",temporary?1:0);}row.put("actor",identities.current().getUsername());if(mapper.update(row)!=1)throw error("工具暂存版本冲突",409);if(!temporary)snapshot(row,"V1.0");return detail(id,selected,temporary);}
 private JSONObject preserveAuthentication(Map<String,Object> row,JSONObject body){var effective=ToolOpenApi.copy(body);var old=JSON.parseObject((String)row.get("configurationJson"));if(!effective.containsKey("appId"))effective.put("appId",old.get("legacyAppId"));if(!body.containsKey("credentialRef")){for(String key:List.of("credentialRef","authenticationMode","hmacConfiguration"))if(old.containsKey(key)&&!effective.containsKey(key))effective.put(key,old.get(key));}return effective;}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED)
 public JSONObject change(long id,Long space,Long revision,boolean delete,boolean enabled){var row=require(id,space,delete?"paiflow:tool:remove":"paiflow:tool:edit",true);revision(row,revision);row.put("deleted",delete?1:0);row.put("enabled",enabled?1:0);row.put("actor",identities.current().getUsername());if(mapper.update(row)!=1)throw error("工具版本已改变",409);return JSONObject.of("id",id,"revision",revision+1,"disabled",!enabled,"deleted",delete);}
 public List<JSONObject> versions(String plugin,Long space){var row=mapper.byPlugin(plugin);if(row==null)throw error("工具不存在或不可访问",404);require(number(row,"id"),space,"paiflow:tool:query",false);return mapper.versions(number(row,"id")).stream().map(v->JSONObject.of("id",v.get("id"),"toolId",plugin,"version",v.get("legacyVersion"),"createTime",v.get("createTime"))).toList();}
 private void snapshot(Map<String,Object> row,String label){var v=new LinkedHashMap<String,Object>();v.put("toolId",row.get("id"));v.put("spaceId",row.get("spaceId"));v.put("ownerUserId",row.get("ownerUserId"));v.put("legacyVersion",label);v.put("configurationJson",row.get("configurationJson"));v.put("configurationHash",DataRuntimeCatalog.sha((String)row.get("configurationJson")));if(mapper.version(v)!=1)throw error("工具版本保存失败",500);}
 private Map<String,Object> require(long id,Long space,String permission,boolean lock){var before=mapper.find(id);if(before==null||space==null||number(before,"spaceId")!=space)throw error("工具不存在或不可访问",404);access.requireSpace(space,permission,lock?2:3,lock);var row=lock?mapper.lock(id):mapper.find(id);if(row==null||number(row,"spaceId")!=space)throw error("工具不存在或不可访问",404);return row;}
 static void revision(Map<String,Object> row,Long expected){if(expected==null||expected!=number(row,"revision"))throw error("工具revision缺失或冲突",409);}
 static long number(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
 static JSONObject configuration(JSONObject body){
  var api=body.get("openApiSchema") instanceof JSONObject o?o:body.get("schema") instanceof String s&&!s.isBlank()?JSON.parseObject(s):body.get("schema") instanceof JSONObject o?o:ToolSchema.fromWeb(body);
  if(!(api.get("servers") instanceof JSONArray supplied)||supplied.isEmpty()){String original=ToolSchema.text(body.get("endPoint"),2048,"endPoint");java.net.URI endpoint=java.net.URI.create(original);String path=endpoint.getRawPath();if(path==null||path.isEmpty())path="/";var fixed=ToolSchema.operations(api);String selected=body.getString("operationId");var operation=selected==null&&fixed.size()==1?fixed.values().iterator().next():fixed.get(selected);if(operation==null||!path.endsWith(operation.path()))throw error("工具管理endpoint与固定schema路径不一致",422);String prefix=path.substring(0,path.length()-operation.path().length());api=ToolOpenApi.copy(api);api.put("servers",new JSONArray(List.of(JSONObject.of("url",endpoint.getScheme()+"://"+endpoint.getRawAuthority()+prefix))));}ToolSchema.budgetApi(api);var operations=ToolSchema.operations(api);ToolSchema.guardApi(api);var servers=api.getJSONArray("servers");if(servers==null||servers.isEmpty())throw error("工具缺少固定server",422);String endpoint=ToolSchema.text(servers.getJSONObject(0).get("url"),2048,"server");java.net.URI uri;try{uri=java.net.URI.create(endpoint);}catch(RuntimeException e){throw error("工具server无效",422);}if(!Set.of("https","http").contains(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getFragment()!=null||uri.getRawQuery()!=null)throw error("工具server无效",422);
  String effect=body.getString("effectClass","write");if(!Set.of("read","write").contains(effect))throw error("工具必须明确read/write副作用类别；不按HTTP方法推断",422);
  var config=JSONObject.of("openApiSchema",api,"effectClass",effect,"legacyAppId",body.getOrDefault("appId",""),"description",body.getOrDefault("description",""),"icon",body.getOrDefault("icon",""),"color",body.getOrDefault("color",""),"webSchema",body.getOrDefault("webSchema",""));
  if(!(config.get("legacyAppId") instanceof String))throw error("原appId必须为字符串兼容标签",422);
  if(body.get("credentialRef")!=null)config.put("credentialRef",ToolSchema.text(body.get("credentialRef"),256,"credentialRef"));
  if(body.get("authInfo")!=null&&!"".equals(body.get("authInfo")))throw error("旧工具明文authInfo不迁入；使用中心credentialRef和批准用途认证注入",422);
  ToolHttpAuthentication.configure(config,body);if(operations.isEmpty())throw error("工具没有operation",422);return config;
 }
 private JSONObject view(Map<String,Object> row){var c=JSON.parseObject((String)row.get("configurationJson"));var api=ToolSchema.publicApi(c.getJSONObject("openApiSchema"));var result=JSONObject.of("id",row.get("id"),"toolId",row.get("pluginId"),"pluginId",row.get("pluginId"),"name",row.get("name"),"description",c.get("description"),"icon",c.get("icon"),"color",c.get("color"),"appId",c.get("legacyAppId"),"spaceId",DefaultPersonalSpaceService.legacySpaceId(access.requireSpace(number(row,"spaceId"),"paiflow:tool:query",3,false)),"userId",row.get("ownerUserId").toString(),"revision",row.get("revision"),"enabled",number(row,"enabled")==1,"temporary",number(row,"temporary")==1,"webSchema",c.get("webSchema"),"schema",api.toJSONString(JSONWriter.Feature.WriteMapNullValue),"openApiSchema",api,"effectClass",c.get("effectClass"),"authConfigured",c.containsKey("credentialRef"),"createTime",row.get("createTime"),"updateTime",row.get("updateTime"));var operation=ToolSchema.operations(c.getJSONObject("openApiSchema")).values().iterator().next();result.put("method",operation.method().toLowerCase(Locale.ROOT));result.put("endPoint",c.getJSONObject("openApiSchema").getJSONArray("servers").getJSONObject(0).getString("url")+operation.path());result.put("operationId",operation.schema().get("operationId"));result.put("deleted",false);result.put("status",number(row,"temporary")==1?0:1);result.put("isMcp",false);result.put("authType","none".equals(ToolHttpAuthentication.mode(c))?0:1);result.put("authInfo","");result.put("credentialRef",c.get("credentialRef"));result.put("authenticationMode",ToolHttpAuthentication.mode(c));result.put("avatarIcon",c.get("icon"));result.put("avatarColor",c.get("color"));result.put("temporaryData",row.get("draftConfigurationJson"));var versions=mapper.versions(number(row,"id"));result.put("version",versions.isEmpty()?null:versions.getFirst().get("legacyVersion"));return result;}
}
